// Process individual action capture
const action = $json;

// Validate action data
if (!action.type && !action.action) {
  return [{
    json: {
      success: false,
      error: 'Invalid action data - missing type or action field',
      received: action
    }
  }];
}

// Process and store action
const processedAction = {
  sessionId: action.sessionId || `session_${Date.now()}`,
  actionType: action.type || action.action || 'unknown',
  element: action.element || '',
  value: action.value || '',
  url: action.url || '',
  timestamp: action.timestamp || new Date().toISOString(),
  processedAt: new Date().toISOString()
};

console.log('✅ Action captured successfully:', processedAction.actionType);

return [{json: processedAction}];

// Return success response for action capture
return [{
  json: {
    success: true,
    message: 'Action captured successfully in TestBuilder',
    sessionId: $json.sessionId,
    actionType: $json.actionType,
    timestamp: new Date().toISOString(),
    status: 'stored'
  }
}];

// Process test generation request
const request = $json;

// Validate session ID
if (!request.sessionId) {
  return [{
    json: {
      success: false,
      error: 'Session ID required for test generation'
    }
  }];
}

// Prepare mock test generation (without AI for now)
const generationRequest = {
  sessionId: request.sessionId,
  actions: request.actions || [],
  pageTitle: request.pageTitle || 'Test Page',
  pageUrl: request.pageUrl || 'http://example.com',
  requestedAt: new Date().toISOString()
};

console.log('🔄 Preparing test generation for session:', request.sessionId);

return [{json: generationRequest}];

// Generate mock test code (without AI integration for testing)
const data = $json;
const actions = data.actions || [];

// Create mock test code
const mockTestCode = `
// GENERATED TEST CODE
// Session: ${data.sessionId}
// Page: ${data.pageTitle}
// URL: ${data.pageUrl}
// Actions captured: ${actions.length}

// Selenium WebDriver Test (Python)
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

def test_recorded_actions():
    driver = webdriver.Chrome()
    driver.get("${data.pageUrl}")

    # Generated actions:
${actions.map((action, i) => `    # Action ${i + 1}: ${action.type || 'unknown'} on ${action.element || 'element'}`).join('\n')}

    driver.quit()

// Playwright Test (JavaScript)
const { test, expect } = require('@playwright/test');

test('recorded actions test', async ({ page }) => {
  await page.goto('${data.pageUrl}');

  // Generated actions:
${actions.map((action, i) => `  // Action ${i + 1}: ${action.type || 'unknown'} on ${action.element || 'element'}`).join('\n')}
});
`;

const finalResponse = {
  success: true,
  sessionId: data.sessionId,
  generatedTests: mockTestCode,
  generatedAt: new Date().toISOString(),
  actionCount: actions.length,
  note: 'Mock test generation - AI integration pending'
};

console.log('✅ Tests generated for session:', data.sessionId);

return [{json: finalResponse}];
